        // ============================================================
        // RELATIONSHIPS COLUMN SECTION
        // ============================================================
        divider_relationships_col: {
            type: 'divider',
            label: '🔗 RELATIONSHIPS COLUMN'
        },

        sa_enable_relationships_column: {
            label: 'Enable Relationships column',
            type: 'checkbox',
            default: true,
            description: 'When enabled and the page type declares injectedColumns:["Relationships"], '
                         + 'a synthetic "Relationships" column is injected and populated '
                         + 'asynchronously with favicon icon links from the MusicBrainz Web Service '
                         + '(the URL relationships of each row\'s release, release group, label '
                         + 'or work, plus release and release-group relationships that have an '
                         + 'icon, e.g. "single from"). Applies to every page type that declares '
                         + 'the column: artist, label, area, release-group and recording release '
                         + 'listings, collections, series, tag pages, reports and search results '
                         + 'among them. Disable to suppress the column entirely. '
                         + 'Adapted from "Display shortcut for relationships on MusicBrainz" '
                         + 'by Aurelien Mino <aurelien.mino@gmail.com>'
        },

        sa_rel_collapse_threshold: {
            label: 'Relationships auto-collapse threshold (unique entities)',
            type: 'number',
            default: 200,
            min: 0,
            max: 100000,
            description: 'A table whose Relationships column would need MORE than this many '
                         + 'distinct MusicBrainz entities starts COLLAPSED: the column and its '
                         + 'cells are there, but nothing is fetched until you press the '
                         + '▶🔗 toggle in that table\'s column header. '
                         + 'The count is the number of Web Service requests the column would '
                         + 'issue, and they are throttled to one per second, so a 2 000-row '
                         + 'release listing costs roughly half an hour of background fetching. '
                         + 'Set to 0 to never auto-collapse (the pre-9.99.1060 behaviour). '
                         + 'The toggle is always available either way, and a table restored '
                         + 'from a saved snapshot always starts expanded because its data is '
                         + 'already there.'
        },

        sa_rel_cell_state_glyphs: {
            label: 'Relationships: show a load-state glyph in each cell',
            type: 'checkbox',
            default: true,
            description: 'Draws a small, faint glyph in every Relationships cell saying where that row '
                         + 'stands: 🔗 not loaded yet (click it to load just that row, one request), '
                         + '⋯ queued, ◌ loading, – loaded but nothing with an icon, ⚠ the request failed '
                         + '(click to retry). Hovering a loaded cell shows ⟳: clicking the cell outside '
                         + 'its icons re-fetches that row. The glyphs are drawn by CSS, so filtering, '
                         + 'sorting and exports never see them. Disable to hide the glyphs and turn '
                         + 'click-to-load off.'
        },

        sa_rel_auto_retry_failed: {
            label: 'Relationships: retry failed lookups once, automatically',
            type: 'checkbox',
            default: true,
            description: 'When the Web Service refuses a few rows during a burst, wait half a minute '
                         + 'after everything else has finished and quietly ask about just those rows '
                         + 'again \u2014 up to two times. Most bursts are over by then, so the \u26a0 cells '
                         + 'simply become icons. It never runs on more than 25 failed rows (that many '
                         + 'is an outage, not a burst) and it gives up immediately after 5 refusals in '
                         + 'a row, so a Web Service that is genuinely down is asked a handful of times '
                         + 'and then left alone. Turn this off to retry only by hand, with the \u26a0\u27f3 '
                         + 'button.'
        },

        sa_rel_auto_retry_max_failed: {
            label: 'Relationships: largest failure count still worth retrying automatically',
            type: 'number',
            default: 25,
            min: 0,
            description: 'Above this many failed rows, the automatic retry above does not run at all: '
                         + 'that many refusals is the Web Service being down rather than briefly busy, '
                         + 'and asking again would only add to its load. Set to 0 to disable the '
                         + 'automatic retry by this route. The \u26a0\u27f3 button is unaffected and always '
                         + 'retries exactly what failed, however many that is.'
        },

        sa_rel_browse_batch_enable: {
            label: 'Relationships: fetch whole pages at once where MusicBrainz allows it',
            type: 'checkbox',
            default: true,
            description: 'On an artist\'s releases, release groups or works, a label\'s releases, a release '
                         + 'group\'s or recording\'s releases, and an area\'s labels, the Relationships '
                         + 'column asks the Web Service for up to 100 entities per request instead of one '
                         + 'per row — about 24 requests instead of 2 300 for a large discography. Rows the '
                         + 'bulk answer does not cover are still looked up one by one, and bulk fetching '
                         + 'stops on its own when one-by-one would be cheaper. Disable to always look rows '
                         + 'up one at a time.'
        },

        sa_rels_idb_enable: {
            label: 'Enable IndexedDB Relationships WS2 data cache',
            type: 'checkbox',
            default: true,
            description: 'Cache MusicBrainz WS2 relationship data in IndexedDB so that '
                         + 'the same page does not re-fetch from the network on every visit. '
                         + 'Cached entries are keyed by entity type + MBID and expire after '
                         + 'sa_rel_idb_ttl_days. Disable to always fetch fresh data from the network. '
                         + 'Uses the same IndexedDB database as the artwork cache '
                         + '(vz-mb-saed-art-cache, store: rel-ws2).'
        },

        sa_rel_idb_ttl_days: {
            label: 'Relationships IDB cache TTL (days)',
            type: 'number',
            default: 30,
            min: 1,
            max: 365,
            description: 'Maximum age in days for a cached WS2 relationship record '
                         + '(IndexedDB store "rel-ws2") before it is considered expired and '
                         + 're-fetched from the network. Mirrors sa_art_idb_image_ttl_days '
                         + 'for the artwork cache.'
        },

        sa_rel_completion_toast_duration: {
            label: 'Relationships load-complete toast duration (seconds)',
            type: 'number',
            default: 8,
            min: 0,
            max: 60,
            description: 'When all Relationships column cells have been populated '
                         + 'with favicon icon links, a small non-intrusive toast notification '
                         + 'appears in the bottom-right corner confirming completion. '
                         + 'It dismisses automatically after this many seconds, or immediately '
                         + 'on click. Set to 0 to disable the notification entirely.'
        },

        sa_enable_relationship_debug: {
            label: 'Enable Relationships column debug logging',
            type: 'checkbox',
            default: false,
            description: 'Enable detailed console logging for the Relationships column pipeline: '
                         + 'MBID extraction per row, WS2 fetch requests and responses, icon class '
                         + 'resolution, favicon probing, and cell population. '
                         + 'Uses Lib.debug(\'relationships\', ...) — requires \'Enable debug logging\' '
                         + 'to also be active. '
        },

