            if (localeNotPrimaryCount > 0) makeSynItem('locale-not-primary', '◦ not primary', localeNotPrimaryCount);
            if (instrumentHasCommentCount > 0)     makeSynItem('instrument-has-comment', '💬 has comment', instrumentHasCommentCount);
            if (instrumentHasDescriptionCount > 0) makeSynItem('instrument-has-description', '📝 has description', instrumentHasDescriptionCount);
            // "Pending edits - Presence"/"- Entity" — see the identical
            // block in the collapsable-column branch above for why these
            // are gated on pendingEditsYesCount rather than emitted
            // unconditionally like every other flag here.
            if (pendingEditsYesCount > 0) {
                makeSynItem('pending-edits-yes', '⏳ has pending edits', pendingEditsYesCount);
                if (pendingEditsNoCount > 0) makeSynItem('pending-edits-no', '○ no pending edits', pendingEditsNoCount);
                _sortedPendingEditValues.forEach(v => makeValueSynItem('pendingedit', v, pendingEditValueCounts.get(v)));
            }
            _sortedAttrValues.forEach(v => makeValueSynItem('attr', v, attrValueCounts.get(v)));
            _sortedTaskValues.forEach(v => makeValueSynItem('task', v, taskValueCounts.get(v)));
            _sortedDateValues.forEach(v => makeValueSynItem('date', v, dateValueCounts.get(v)));
            _sortedEventDateValues.forEach(v => makeValueSynItem('eventdate', v, eventDateValueCounts.get(v)));
            _sortedInstrumentValues.forEach(v => makeValueSynItem('instrument', v, instrumentValueCounts.get(v)));
            _sortedAltNameValues.forEach(v => makeValueSynItem('altname', v, altNameValueCounts.get(v)));
            _sortedNameValues.forEach(v => _emitNameSynItem(v));
            _sortedCommentValues.forEach(v => makeValueSynItem('comment', v, entityCommentValueCounts.get(v)));
            _sortedAliasValues.forEach(v => { if (!_alreadyOfferedBareNames.has(v)) makeValueSynItem('alias', v, entityAliasValueCounts.get(v)); });
            _sortedTagCountValues.forEach(v => makeValueSynItem('tagcount', v, entityTagCountValueCounts.get(v)));
            if (_eventCancelledKind) _sortedEventCancelledValues.forEach(v => makeValueSynItem(_eventCancelledKind, v, eventCancelledValueCounts.get(v)));
            _sortedJoinPhraseValues.forEach(v => makeValueSynItem('joinphrase', v, joinPhraseValueCounts.get(v)));
            _sortedNameVariationValues.forEach(v => makeValueSynItem('namevariation', v, nameVariationValueCounts.get(v)));
            _sortedFormatSizeValues.forEach(v => makeValueSynItem('formatsize', v, formatSizeValueCounts.get(v)));
            _sortedFormatCountValues.forEach(v => makeValueSynItem('formatcount', v, formatCountValueCounts.get(v)));
            _sortedFormatComboValues.forEach(v => makeValueSynItem('formatcombo', v, formatComboValueCounts.get(v)));
            _sortedFormatTypeValues.forEach(v => makeValueSynItem('formattype', v, formatTypeValueCounts.get(v)));
            _sortedRecAttrValues.forEach(v => makeValueSynItem('recattr', v, recAttrValueCounts.get(v)));
            _sortedWorkAttrIdValues.forEach(v => makeValueSynItem('workattrid', v, workAttrIdValueCounts.get(v)));
            _sortedTitleAgeAddedValues.forEach(v => makeValueSynItem('titleageadded', v, titleAgeAddedValueCounts.get(v)));
            _sortedTitleAgeModifiedValues.forEach(v => makeValueSynItem('titleagemodified', v, titleAgeModifiedValueCounts.get(v)));
            _sortedRevCountryValues.forEach(v => makeValueSynItem('revcountry', v, revCountryValueCounts.get(v), revCountryFlagMap.get(v)));
            _sortedRevDateValues.forEach(v => makeValueSynItem('revdate', v, revDateValueCounts.get(v)));
            _sortedRevWeekdayValues.forEach(v => makeValueSynItem('revweekday', v, revWeekdayValueCounts.get(v)));
            _sortedCountryNameValues.forEach(v => makeValueSynItem('countryname', v, countryNameValueCounts.get(v), countryNameFlagMap.get(v)));
            _sortedCountryCodeValues.forEach(v => makeValueSynItem('countrycode', v, countryCodeValueCounts.get(v), countryCodeFlagMap.get(v)));
            _sortedTracksPerMediumValues.forEach(v => makeValueSynItem('trackspermedium', v, tracksPerMediumValueCounts.get(v)));
            _sortedTracksTotalValues.forEach(v => makeValueSynItem('trackstotal', v, tracksTotalValueCounts.get(v)));
            _sortedCatalogPrefixValues.forEach(v => makeValueSynItem('catalogprefix', v, catalogPrefixValueCounts.get(v)));
            _sortedIsrcCountryValues.forEach(v => makeValueSynItem('isrccountry', v, isrcCountryValueCounts.get(v)));
            _sortedIsrcRegistrantValues.forEach(v => makeValueSynItem('isrcregistrant', v, isrcRegistrantValueCounts.get(v)));
            _sortedIsrcYearValues.forEach(v => makeValueSynItem('isrcyear', v, isrcYearValueCounts.get(v)));
            _sortedIsrcDesignationValues.forEach(v => makeValueSynItem('isrcdesignation', v, isrcDesignationValueCounts.get(v)));
            _sortedBarcodeFormatValues.forEach(v => makeValueSynItem('barcodeformat', v, barcodeFormatValueCounts.get(v)));
