        if (mode.startsWith('isrcdesignation:')) return `» designation: ${mode.slice(16)}`;
        if (mode.startsWith('lengthbucket:'))    return `» duration: ${mode.slice(13)}`;
        if (mode.startsWith('timeofday:'))       return `» time of day: ${mode.slice(10)}`;
        if (mode.startsWith('reltypecredit:'))   return `» ${mode.slice(14)}`;
        if (mode.startsWith('partofseriesname:'))   return `» series name: ${mode.slice(18)}`;
        if (mode.startsWith('partofseriesdate:'))   return `» date: ${mode.slice(17)}`;
        if (mode.startsWith('partofseriesnumber:')) return `» number: ${mode.slice(19)}`;
        if (mode.startsWith('role:'))    return `» role: ${mode.slice(5)}`;
        if (mode.startsWith('roletoken:')) return `» role: ${mode.slice(10)}`;
        if (mode.startsWith('arttype:'))    return `» image type: ${mode.slice(8)}`;
        if (mode.startsWith('artcomment:')) return `» image comment: ${mode.slice(11)}`;
        if (mode === 'rel-state-pending')   return '🔗 not loaded yet';
        if (mode === 'rel-state-has')       return '✓ has relationships';
        if (mode === 'rel-state-none')      return '– no relationships';
        if (mode === 'rel-state-error')     return '⚠ request failed';
        if (mode.startsWith('rel:'))        return `🔗 ${mode.slice(4)}`;
        if (mode === 'editor-any-deleted')      return '🗑️ any deleted editor';
        if (mode === 'changelog-has-message')   return '📜 has changelog message';
        if (mode === 'changelog-no-message')    return '🚫 no changelog specified';
        if (mode.startsWith('editordeleted:'))      return `» deleted editor: ${mode.slice(14)}`;
        if (mode.startsWith('editorrecordedname:')) return `» recorded name: ${mode.slice(19)}`;
        if (mode.startsWith('editormembership:'))   return `» membership: ${mode.slice(17)}`;
        if (mode.startsWith('editorcomment:'))      return `» comment: ${mode.slice(14)}`;
        if (mode === 'release-quality-high')   return '🟢 high data quality';
        if (mode === 'release-quality-low')    return '🟠 low data quality';
        if (mode === 'release-quality-normal') return '⚪ normal data quality';
        if (mode === 'acoustid-linked')   return '🔗 linked';
        if (mode === 'acoustid-unlinked') return '🚫 unlinked';
        if (mode === 'length-ms-precise')             return '🔬 milliseconds ≠ .000';
        if (mode === 'length-ms-whole')               return '⭕ milliseconds = .000 (whole seconds)';
        if (mode === 'length-ms-none')                return '∅ no millisecond data';
        if (mode === 'lengthdeviation-within10')      return '🎯 within 10% of average';
        if (mode === 'lengthdeviation-shorter10to25') return '🔽 10–25% shorter than average';
        if (mode === 'lengthdeviation-longer10to25')  return '🔼 10–25% longer than average';
        if (mode === 'lengthdeviation-shorter25to50') return '⏬ 25–50% shorter than average';
        if (mode === 'lengthdeviation-longer25to50')  return '⏫ 25–50% longer than average';
        if (mode === 'lengthdeviation-shorter50plus') return '⬇️ 50%+ shorter than average';
        if (mode === 'lengthdeviation-longer50plus')  return '⬆️ 50%+ longer than average';
        if (mode === 'lengthlive-yes') return '🎙️ Live recording';
        if (mode === 'lengthlive-no')  return '⚪ Not live';
